package com.sshop.service;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.sshop.common.BizException; import com.sshop.entity.*; import com.sshop.mapper.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service public class OrderService { private final OrderMapper orders; private final OrderItemMapper items; private final GoodsMapper goods; private final ShopConfigMapper configs; private final SubscribeMessageService subscribeMessages; public OrderService(OrderMapper o,OrderItemMapper i,GoodsMapper g,ShopConfigMapper c,SubscribeMessageService s){orders=o;items=i;goods=g;configs=c;subscribeMessages=s;}
  public Map<String,Object> detail(Long id){Order o=orders.selectById(id);if(o==null)throw new BizException("订单不存在");ShopConfig config=configs.selectById(1);Map<String,Object> m=new LinkedHashMap<>();m.put("order",o);m.put("itemList",items.selectList(new QueryWrapper<OrderItem>().eq("order_no",o.getOrderNo()).eq("del_flag",0)));m.put("payQrcode",config==null?null:config.getPayQrcode());m.put("deliveryTip",config==null?null:config.getDeliveryTip());return m;}
  @Transactional public Order create(Long uid,String addressInfo,String remark,List<Map<String,Object>> lines){ShopConfig config=configs.selectById(1);if(config!=null&&Integer.valueOf(0).equals(config.getShopStatus()))throw new BizException("店铺歇业中，暂不接受订单");if(lines==null||lines.isEmpty())throw new BizException("商品不能为空");Map<Long,Integer> quantities=new LinkedHashMap<>();for(Map<String,Object> line:lines){Object goodsId=line.get("goodsId");Object goodsNum=line.get("goodsNum");if(!(goodsId instanceof Number)||!(goodsNum instanceof Number))throw new BizException("商品参数错误");int qty=((Number)goodsNum).intValue();if(qty<1)throw new BizException("商品数量必须大于0");long gid=((Number)goodsId).longValue();quantities.merge(gid,qty,Math::addExact);}Order o=new Order();o.setOrderNo("S"+System.currentTimeMillis()+uid);o.setUserId(uid);o.setOrderStatus(0);o.setDelFlag(0);o.setAddressInfo(addressInfo);o.setRemark(remark);BigDecimal total=BigDecimal.ZERO;orders.insert(o);for(Map.Entry<Long,Integer> entry:quantities.entrySet()){long gid=entry.getKey();int qty=entry.getValue();Goods g=goods.selectById(gid);if(g==null||g.getGoodsStatus()!=1||g.getDelFlag()!=0)throw new BizException("商品未上架或不存在");if(goods.deductStock(gid,qty)!=1)throw new BizException("商品库存不足: "+g.getGoodsName());OrderItem x=new OrderItem();x.setOrderNo(o.getOrderNo());x.setGoodsId(gid);x.setGoodsName(g.getGoodsName());x.setGoodsPrice(g.getGoodsPrice());x.setGoodsNum(qty);x.setDelFlag(0);items.insert(x);total=total.add(g.getGoodsPrice().multiply(BigDecimal.valueOf(qty)));}o.setTotalAmount(total);orders.updateById(o);subscribeMessages.send(uid,o.getOrderNo());return o;}
  @Transactional public Order transition(Long id,int target){Order o=orders.selectById(id);if(o==null)throw new BizException("订单不存在");int current=o.getOrderStatus();if(!((current==0&&(target==1||target==3))||(current==1&&target==2)))throw new BizException("非法订单状态流转");if(target==3){List<OrderItem> orderItems=items.selectList(new QueryWrapper<OrderItem>().eq("order_no",o.getOrderNo()).eq("del_flag",0));for(OrderItem item:orderItems)goods.restoreStock(item.getGoodsId(),item.getGoodsNum());}o.setOrderStatus(target);orders.updateById(o);return o;}
}
